import{_ as l,c as i,o as e,ag as t}from"./chunks/framework.B1jFR3yW.js";const p=JSON.parse('{"title":"005 决策树","description":"","frontmatter":{},"headers":[],"relativePath":"python/机器学习/005决策树.md","filePath":"python/机器学习/005决策树.md"}'),r={name:"python/机器学习/005决策树.md"};function o(h,a,n,d,u,s){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="_005-决策树" tabindex="-1">005 决策树 <a class="header-anchor" href="#_005-决策树" aria-label="Permalink to &quot;005 决策树&quot;">​</a></h1><h2 id="决策树是什么" tabindex="-1">决策树是什么 <a class="header-anchor" href="#决策树是什么" aria-label="Permalink to &quot;决策树是什么&quot;">​</a></h2><p>决策树是一种通过不断“提问”和“切分数据”来完成预测的模型。</p><p>你可以把它理解成一连串条件判断：</p><ul><li>如果年龄小于某值</li><li>并且收入高于某值</li><li>那么更可能属于某一类</li></ul><h2 id="决策树能做什么" tabindex="-1">决策树能做什么 <a class="header-anchor" href="#决策树能做什么" aria-label="Permalink to &quot;决策树能做什么&quot;">​</a></h2><ul><li>分类</li><li>回归</li></ul><h2 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to &quot;核心思想&quot;">​</a></h2><p>从根节点开始，选择一个最合适的特征进行划分，让数据被一步步分成更纯的子集，直到满足停止条件。</p><h2 id="常见划分指标" tabindex="-1">常见划分指标 <a class="header-anchor" href="#常见划分指标" aria-label="Permalink to &quot;常见划分指标&quot;">​</a></h2><ul><li>信息增益</li><li>信息增益率</li><li>基尼指数</li></ul><p>不同树算法使用的划分标准可能不同。</p><h2 id="决策树的优缺点" tabindex="-1">决策树的优缺点 <a class="header-anchor" href="#决策树的优缺点" aria-label="Permalink to &quot;决策树的优缺点&quot;">​</a></h2><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h3><ul><li>很直观</li><li>可解释性强</li><li>能处理非线性关系</li><li>对数据预处理要求相对低</li></ul><h3 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h3><ul><li>容易过拟合</li><li>单棵树稳定性较差</li></ul><h2 id="如何缓解过拟合" tabindex="-1">如何缓解过拟合 <a class="header-anchor" href="#如何缓解过拟合" aria-label="Permalink to &quot;如何缓解过拟合&quot;">​</a></h2><p>常见方法包括：</p><ul><li>限制树深度</li><li>限制叶子节点最少样本数</li><li>做剪枝</li></ul><h2 id="决策树适合什么场景" tabindex="-1">决策树适合什么场景 <a class="header-anchor" href="#决策树适合什么场景" aria-label="Permalink to &quot;决策树适合什么场景&quot;">​</a></h2><p>如果你希望：</p><ul><li>模型比较容易解释</li><li>快速建立一个可读规则系统</li><li>对特征之间的非线性关系建模</li></ul><p>决策树是很常见的起点。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><p>学习决策树时，要重点抓住：</p><ul><li>它的本质是不断划分数据</li><li>它可解释性强</li><li>它容易过拟合</li><li>它也是很多集成学习模型的基础</li></ul>',27)])])}const _=l(r,[["render",o]]);export{p as __pageData,_ as default};
